"""Official capture of the unique owned paper source/native frame."""
import argparse,base64,json
from pathlib import Path
from driver import ps,q
r=Path(__file__).resolve().parents[2];p=argparse.ArgumentParser();p.add_argument('--source',action='store_true');p.add_argument('--manifest',type=Path,required=True);a=p.parse_args();assert json.loads((r/'docs/replica/ENVIRONMENT_LEASE.json').read_text())['resources']['windows']['owner']=='home';m=json.loads(a.manifest.read_text());s=json.loads((a.manifest.parent/'windows-stage.json').read_text());assert m['owner']=='home' and m['component']=='welcomepaper'
base="$app=Join-Path (Join-Path $env:TEMP "+q(s['guestFolder'])+") 'app';"
filter="$_.Current.Name.StartsWith('WelcomePaper · original isolation') -and (Get-Process -Id $_.Current.ProcessId).Path.EndsWith('\\Microsoft\\Edge\\Application\\msedge.exe')" if a.source else "$_.Current.Name-eq 'Replica WelcomePaper verification' -and (Get-Process -Id $_.Current.ProcessId).Path-eq ($app+'\\ReplicaProbe.exe')"
code=('' if a.source else base)+"Add-Type -AssemblyName System.Drawing;$ws=[System.Windows.Automation.AutomationElement]::RootElement.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition);$w=@($ws|Where-Object{"+filter+"});if($w.Count-ne1){throw 'Unique owned capture required'};$w=$w[0];$b=$w.FindFirst([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.PropertyCondition]::new([System.Windows.Automation.AutomationElement]::AutomationIdProperty,'WelcomePaper-research'));if($null-eq$b){throw 'Owned button missing'};$b.SetFocus();Add-Type 'using System;using System.Runtime.InteropServices;public static class PaperCaptureGuard{[DllImport(\"user32.dll\")]public static extern IntPtr GetForegroundWindow();}';if([PaperCaptureGuard]::GetForegroundWindow().ToInt64()-ne $w.Current.NativeWindowHandle){throw 'Capture foreground mismatch'};$r=$w.Current.BoundingRectangle;if($r.Width-lt500-or$r.Width-gt4000-or$r.Height-lt400-or$r.Height-gt2400){throw 'Wrong owned capture bounds'};$bmp=[Drawing.Bitmap]::new([int]$r.Width,[int]$r.Height);$g=[Drawing.Graphics]::FromImage($bmp);$g.CopyFromScreen([int]$r.Left,[int]$r.Top,0,0,$bmp.Size);$ms=[IO.MemoryStream]::new();$bmp.Save($ms,[Drawing.Imaging.ImageFormat]::Png);[Console]::WriteLine([Convert]::ToBase64String($ms.ToArray()));$g.Dispose();$bmp.Dispose();$ms.Dispose();"
code=code.replace('[System.Windows.Automation.AutomationElement]', '$A').replace('[System.Windows.Automation.TreeScope]', '$T');code='$A=[System.Windows.Automation.AutomationElement];$T=[System.Windows.Automation.TreeScope];'+code
out=r/'docs/replica/source/welcomepaper-windows-input';out.mkdir(exist_ok=True);target=out/('source-frame.png' if a.source else 'native-frame.png');target.write_bytes(base64.b64decode(ps(code)));print(target)
